"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["64635"],{45191(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.id_etapa_duplicado","status":422,"titulo":"O mesmo identificador de etapa aparece em mais de uma etapa"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.id_etapa_duplicado","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["O corpo do pedido de defini\xe7\xe3o de etapas informou o mesmo `Id` em mais de um item do\\narray. Ao substituir a cole\xe7\xe3o de etapas, o sistema reconcilia por `Id`: uma\\netapa cujo `Id` (ecoado pelo cliente a partir de uma leitura anterior) ainda\\nexiste no processo \xe9 **atualizada** na mesma inst\xe2ncia \u2014 o que preserva\\nrefer\xeancias que crit\xe9rios de desempate ou regras de elimina\xe7\xe3o j\xe1 apontem para\\nela. Dois itens com o mesmo `Id` no mesmo corpo do pedido tornam essa reconcilia\xe7\xe3o\\namb\xedgua: n\xe3o h\xe1 como decidir qual dos dois representa a etapa existente.","Uma etapa **nova** n\xe3o tem esse problema \u2014 o campo `Id` \xe9 opcional na cria\xe7\xe3o,\\natribu\xeddo pelo sistema; a confer\xeancia s\xf3 rejeita repeti\xe7\xe3o entre `Id`s\\nefetivamente informados."],"comoResolver":["Revise o array de etapas enviado e garanta que cada `Id` informado apare\xe7a no\\nm\xe1ximo uma vez. Etapas novas n\xe3o precisam de `Id` \u2014 omita o campo em vez de\\ninventar um valor, e deixe o sistema atribuir um na cria\xe7\xe3o."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);